def _needs_healing(self, layout: st.Layout) -> bool:
    """Whether a shared read must escalate to heal before reading.

    A read escalates when the live path is absent and a migration
    backup is waiting -- without adoption there is nothing to read --
    and when an archived store physically straddles the two tiers (a
    hot duplicate of an archived segment, or an orphan/temp left in the
    archive directory by a migration killed mid-flight): reopening must
    land on exactly one topology, never on copies kept in both places.
    Every other leftover (staging directory, an unreferenced hot
    segment from a rotation/compaction killed before/after its manifest
    commit, a merge temp file, a post-publish backup) is inert while
    the committed manifest stays authoritative, so reads leave it
    untouched and the next writer (exclusive) reaps it -- matching the
    baseline rule that reads never move garbage out from under other
    readers.
    """
    if not os.path.exists(self.path) and os.path.exists(
        self.path + ".pre-segment"
    ):
        return True
    return self._archive_inconsistency(layout)

@staticmethod
def _archive_inconsistency(layout: st.Layout) -> bool:
    """Whether an archived store physically straddles the two tiers."""
    if layout.kind != "dir":
        return False
    with contextlib.suppress(st.AuditMetadataError):
        manifest = st.load_manifest(layout)
    if manifest is None:
        return False
    archive_dir = manifest.get("archive")
    if not archive_dir:
        return False
    referenced = {segment["name"] for segment in manifest["segments"]}
    for segment in manifest["segments"]:
        if segment.get("archived") and os.path.exists(
            layout.segment_path(segment["name"])
        ):
            # Killed after the manifest commit, before the hot copy was
            # removed: both tiers currently hold the segment.
            return True
    if os.path.isdir(archive_dir):
        for name in os.listdir(archive_dir):
            if st.seg_seq(name) is not None and name not in referenced:
                # Copied by a migration killed before its manifest
                # commit; the hot tier still owns the segment.
                return True
            if name.startswith(".") and name.endswith(".tmp"):
                return True
    return False

