import os, sys, tempfile, time, multiprocessing
from audit_chain import Chain

tmp = tempfile.mkdtemp()
path = os.path.join(tmp, "log")
dest = os.path.join(tmp, "arc")
c = Chain(path)
for r in range(4):
    for i in range(5):
        c.append("t", {"i": r*5+i})
    c.rotate()
c.append("t", {"i": 20})

def archiver():
    ch = Chain(path)
    for _ in range(8):
        try:
            ch.archive(dest)
        except ValueError:
            pass
        time.sleep(0.002)

def compactor():
    ch = Chain(path)
    for _ in range(8):
        try:
            ch.compact(2)
        except ValueError:
            pass
        time.sleep(0.002)

def appender():
    ch = Chain(path)
    for i in range(40):
        ch.append("u", {"i": i})
        # read-your-write immediately
        assert ch.head("u") == ch.entries("u")[-1]["digest"]

ctx = multiprocessing.get_context("fork")
procs = [ctx.Process(target=f) for f in (archiver, compactor, appender)]
for p in procs: p.start()
for p in procs:
    p.join(timeout=120)
    assert p.exitcode == 0, p.exitcode

final = Chain(path)
r = final.verify("t")
assert r["ok"], r
assert final.verify("u") == {"count": 40, "first_bad": -1, "ok": True}
# global order strictly linked, indices continuous
for tenant in ("t", "u"):
    entries = final.entries(tenant)
    for pos, e in enumerate(entries):
        assert e["prev"] == (entries[pos-1]["digest"] if pos else ""), (tenant, pos)
# one topology
import json
m = json.load(open(os.path.join(path, "manifest.json")))
archived = {s["name"] for s in m["segments"] if s.get("archived")}
hot = {n for n in os.listdir(path) if n.startswith("seg-")}
cold = {n for n in os.listdir(dest) if n.startswith("seg-")} if os.path.isdir(dest) else set()
assert not (hot & cold)
assert cold == archived, (cold, archived)
assert not os.path.exists(os.path.join(path, ".archiving"))
print("CONCURRENCY OK", r)
